/**
 * 
 * Calls tools the same way the MCP server does, for tests.
 */
public final class McpToolTesting {
  private McpToolTesting() {
  }

  /**
   * 
   * Runs the tool with the given arguments (a JSON object as text) in the given project. The project must be an
   * MPSProject, because tool bodies get one.
   */
  public static ToolOutcome call(Project project, SyncMcpTool tool, String argsJson) {
    JsonObject args = JsonElementKt.getJsonObject(ToolSchemas.JSON.parseToJsonElement(argsJson));
    return ToolRunner.run(tool, (MPSProject) project, new ToolArgs(args));
  }

  /**
   * 
   * The tool group that the generator produced for the given model. The module of the model must be deployed.
   */
  public static ToolGroup group(Project project, final SModelReference model) {
    final SRepository repository = project.getRepository();
    final AtomicReference<SModuleReference> owner = new AtomicReference<SModuleReference>();
    final AtomicReference<String> modelName = new AtomicReference<String>();
    repository.getModelAccess().runReadAction(() -> {
      {
        SModel resolved = model.resolve(repository);
        if (resolved != null) {
          owner.set(resolved.getModule().getModuleReference());
          modelName.set(resolved.getName().getLongName());
        }
      }
    });
    if (owner.get() == null) {
      throw new IllegalArgumentException("Model " + model + " is not in the repository.");
    }
    String className = ToolGroupDiscovery.groupClassName(modelName.get());
    Map<String, Class<?>> classes = ModuleClasses.ownClasses(project.getComponent(LanguageRegistry.class), owner.get(), Collections.singletonList(className));
    Class<?> groupClass = MapSequence.fromMap(classes).get(className);
    if (groupClass == null) {
      throw new IllegalArgumentException("The classes of the module with model " + modelName.get() + " are not loaded, or the module has no class " + className + ".");
    }
    try {
      return ToolGroupDiscovery.instantiate(groupClass);
    } catch (ReflectiveOperationException e) {
      throw new IllegalStateException("Cannot create the tool group " + className, e);
    }
  }

  /**
   * 
   * The tool with the given name, without the group prefix, from the tool group of the given model.
   */
  public static SyncMcpTool tool(Project project, SModelReference model, String toolName) {
    for (SyncMcpTool tool : ListSequence.fromList(group(project, model).tools())) {
      if (toolName.equals(tool.name())) {
        return tool;
      }
    }
    throw new IllegalArgumentException("Model " + model + " has no tool " + toolName + ".");
  }

  /**
   * 
   * The "properties" object of the tool's input schema as the MCP server sends it, projectPath included.
   */
  public static JsonObject inputProperties(SyncMcpTool tool) {
    return ToolSchemas.inputProperties(tool);
  }

  /**
   * 
   * Parses JSON text, for comparing schemas regardless of formatting.
   */
  public static JsonElement json(String text) {
    return ToolSchemas.JSON.parseToJsonElement(text);
  }
}
